    <div class="px-2 pt-2"><span id="likecount<?= (int)$post['id'] ?>"><?= (int)$post['like_count'] ?></span> Thích <span class="small text-muted ms-2">Đã đăng <?= e(show_time($post['created_at'])) ?></span></div>
