<script>
function reportPost(postId){if(!confirm('Bạn có chắc muốn báo cáo bài viết này không?'))return;const body=new URLSearchParams({post_id:String(postId)});window.handbookFetch('?action=report_post',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:body.toString()}).then(async r=>{const data=await r.json();alert(data.message||'Đã xử lý yêu cầu.');}).catch(()=>alert('Không thể báo cáo bài viết.'));}
</script>
